-- db-01: PostgreSQL DDL for Tediwave; structure only, no data.

CREATE TABLE "adminCustomerRestrictions" (
  "customerId" bigint NOT NULL,
  "restrictionType" varchar(20) NOT NULL,
  "previousStatus" varchar(40) NOT NULL,
  "previousIsPnd" boolean NOT NULL DEFAULT FALSE,
  "reason" text NOT NULL,
  "adminId" bigint NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("customerId")
);

CREATE TABLE "adminKnownDevices" (
  "deviceId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "adminId" integer NOT NULL,
  "fingerprint" varchar(255) NOT NULL,
  "metadata" jsonb DEFAULT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "status" varchar(7) NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'blocked')),
  "firstSeen" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "lastSeen" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("deviceId"),
  CONSTRAINT "adminKnownDevices_uq_admin_known_device" UNIQUE ("adminId","fingerprint")
);

CREATE TABLE "admins" (
  "adminId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "firstName" varchar(100) DEFAULT NULL,
  "middleName" varchar(100) DEFAULT NULL,
  "lastName" varchar(100) DEFAULT NULL,
  "fullName" varchar(100) NOT NULL,
  "email" varchar(150) NOT NULL,
  "passwordHash" varchar(255) NOT NULL,
  "role" varchar(10) DEFAULT 'support' CHECK ("role" IN ('superAdmin', 'manager', 'support')),
  "adminPermissions" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "status" varchar(9) DEFAULT 'active' CHECK ("status" IN ('active', 'suspended')),
  "mode" varchar(4) NOT NULL DEFAULT 'live' CHECK ("mode" IN ('live', 'test')),
  "avatarBlob" bytea,
  "lastLoginAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("adminId"),
  CONSTRAINT "admins_email" UNIQUE ("email")
);

CREATE TABLE "adminSessions" (
  "sessionId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "adminId" integer NOT NULL,
  "sessionToken" varchar(255) NOT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "status" varchar(7) DEFAULT 'active' CHECK ("status" IN ('active', 'expired')),
  "mode" varchar(4) NOT NULL DEFAULT 'live' CHECK ("mode" IN ('live', 'test')),
  "channel" varchar(50) NOT NULL DEFAULT 'web',
  "metadata" jsonb DEFAULT NULL,
  "terminationReason" jsonb DEFAULT NULL,
  "expiresAt" timestamp NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("sessionId"),
  CONSTRAINT "adminSessions_session_token" UNIQUE ("sessionToken"),
  CONSTRAINT "adminSessions_adminSessions_ibfk_1" FOREIGN KEY ("adminId") REFERENCES "admins" ("adminId") ON DELETE CASCADE
);

CREATE TABLE "apiKeys" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "service" varchar(50) NOT NULL,
  "apiKey" text,
  "secretKey" varchar(255) DEFAULT NULL,
  "credentialType" varchar(50) DEFAULT NULL,
  "environment" varchar(50) DEFAULT NULL,
  "clientId" varchar(255) DEFAULT NULL,
  "encryptionKey" varchar(255) DEFAULT NULL,
  "webhookHash" varchar(255) DEFAULT NULL,
  "description" text,
  "isActive" boolean NOT NULL DEFAULT TRUE,
  "updatedAt" timestamp DEFAULT NULL,
  "notes" text,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE INDEX "apiKeys_service_active_id_idx"
  ON "apiKeys" ("service", "isActive", "id");

CREATE TABLE "beneficiaries" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "service" varchar(50) NOT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "metadata" jsonb NOT NULL,
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "deletedAt" timestamp DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "bettingProviders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "serviceCode" varchar(50) NOT NULL,
  "displayName" varchar(100) NOT NULL,
  "logoUrl" varchar(255) DEFAULT NULL,
  "isActive" boolean DEFAULT TRUE,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "betting_providers_service_code" UNIQUE ("serviceCode")
);

CREATE TABLE "campaigns" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(255) NOT NULL,
  "title" varchar(255) NOT NULL,
  "description" text,
  "imageUrl" varchar(512) DEFAULT NULL,
  "destination" varchar(512) DEFAULT NULL,
  "actionType" varchar(50) NOT NULL DEFAULT 'url',
  "platform" varchar(50) NOT NULL DEFAULT 'all',
  "status" varchar(50) NOT NULL DEFAULT 'active',
  "priority" integer DEFAULT '0',
  "startsAt" timestamp NOT NULL,
  "endsAt" timestamp NOT NULL,
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "analytics" jsonb DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "complianceWebhookReceipts" (
  "eventId" char(32) NOT NULL,
  "userId" bigint NOT NULL,
  "receivedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("eventId")
);

CREATE TABLE "cookies" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cacheKey" varchar(191) NOT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "payload" jsonb NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expiresAt" timestamp NOT NULL,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "cookies_ukCookiesCacheKeyEnvironment" UNIQUE ("cacheKey","environment")
);

CREATE TABLE "dailyCheckins" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "checkinDate" date NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "isClaimed" boolean DEFAULT FALSE,
  "rewardClaimed" boolean NOT NULL DEFAULT FALSE,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "daily_checkins_unique_user_day" UNIQUE ("userId","checkinDate")
);

CREATE TABLE "dailyTaskClaims" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL CHECK ("environment" IN ('LIVE', 'TEST')),
  "claimKey" varchar(128) NOT NULL,
  "taskKey" varchar(40) NOT NULL,
  "transactionReference" varchar(100) NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "dailyTaskClaims_uq_user_claim" UNIQUE ("userId", "environment", "claimKey"),
  CONSTRAINT "dailyTaskClaims_uq_transaction_reference" UNIQUE ("transactionReference")
);

CREATE TABLE "dataPlans" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "provider" varchar(50) NOT NULL DEFAULT 'fafotech',
  "providerPlanId" varchar(100) NOT NULL,
  "network" varchar(20) DEFAULT NULL,
  "planType" varchar(50) DEFAULT NULL,
  "planName" varchar(100) DEFAULT NULL,
  "planSize" varchar(50) DEFAULT NULL,
  "providerPrice" decimal(10,2) DEFAULT NULL,
  "sellingPrice" decimal(10,2) DEFAULT NULL,
  "profit" decimal(10,2) NOT NULL DEFAULT '0.00',
  "validity" varchar(100) DEFAULT NULL,
  "platformName" varchar(100) DEFAULT NULL,
  "durationCategory" varchar(50) DEFAULT NULL,
  "lastChecked" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "validityDays" integer NOT NULL DEFAULT '0',
  PRIMARY KEY ("id"),
  CONSTRAINT "data_plans_ukProviderPlan" UNIQUE ("provider","providerPlanId")
);

CREATE TABLE "educationProviders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "serviceName" varchar(50) NOT NULL,
  "productCode" integer NOT NULL,
  "displayName" varchar(100) NOT NULL,
  "price" decimal(10,2) DEFAULT '0.00',
  "isActive" boolean DEFAULT TRUE,
  PRIMARY KEY ("id")
);

CREATE TABLE "featureSuggestions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer DEFAULT NULL,
  "environment" varchar(20) DEFAULT NULL,
  "category" varchar(30) NOT NULL DEFAULT 'other',
  "message" varchar(1000) NOT NULL,
  "email" varchar(255) DEFAULT NULL,
  "platform" varchar(20) DEFAULT NULL,
  "appVersion" varchar(50) DEFAULT NULL,
  "status" varchar(10) NOT NULL DEFAULT 'new' CHECK ("status" IN ('new', 'reviewed', 'planned', 'inProgress', 'completed', 'rejected')),
  "metadata" jsonb DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "giftCardSubmissions" (
  "id" varchar(36) NOT NULL,
  "transactionId" varchar(36) NOT NULL,
  "userId" varchar(36) NOT NULL,
  "brandName" varchar(100) NOT NULL,
  "cardType" varchar(20) NOT NULL,
  "countryCode" varchar(10) NOT NULL,
  "faceValue" decimal(10,2) NOT NULL,
  "cardCurrency" varchar(10) NOT NULL,
  "rateApplied" decimal(10,2) NOT NULL,
  "expectedPayout" decimal(15,2) NOT NULL,
  "payoutCurrency" varchar(10) NOT NULL DEFAULT 'NGN',
  "eCodeString" text,
  "imagePaths" jsonb DEFAULT NULL,
  "receiptPaths" jsonb DEFAULT NULL,
  "adminNotes" text,
  "status" varchar(8) NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'approved', 'failed', 'rejected')),
  "reviewedBy" varchar(36) DEFAULT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "imageData" bytea,
  "receiptData" bytea,
  "submissionHash" char(64) NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "invoices" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoiceNumber" varchar(40) NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(10) NOT NULL,
  "type" varchar(30) NOT NULL DEFAULT 'paymentLink',
  "amount" decimal(18,2) DEFAULT NULL,
  "amountPaid" decimal(18,2) NOT NULL DEFAULT '0.00',
  "isAmountFixed" boolean NOT NULL DEFAULT TRUE,
  "minAmount" decimal(18,2) DEFAULT NULL,
  "maxAmount" decimal(18,2) DEFAULT NULL,
  "currency" varchar(10) NOT NULL,
  "purpose" varchar(50) NOT NULL DEFAULT 'walletDeposit',
  "description" varchar(255) DEFAULT NULL,
  "redirectUrl" varchar(500) DEFAULT NULL,
  "checkoutUrl" varchar(500) DEFAULT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending',
  "paymentMethod" varchar(30) DEFAULT NULL,
  "provider" varchar(30) DEFAULT NULL,
  "providerReference" varchar(100) DEFAULT NULL,
  "transactionId" bigint DEFAULT NULL,
  "document" jsonb DEFAULT NULL,
  "payments" jsonb DEFAULT NULL,
  "metadata" jsonb DEFAULT NULL,
  "expiresAt" timestamp DEFAULT NULL,
  "paidAt" timestamp DEFAULT NULL,
  "endedAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "invoices_uq_invoices_number" UNIQUE ("invoiceNumber")
);

CREATE TABLE "knownDevices" (
  "deviceId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "fingerprint" varchar(255) NOT NULL,
  "deviceModel" varchar(100) DEFAULT NULL,
  "status" varchar(7) NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'blocked')),
  "lastIp" varchar(45) DEFAULT NULL,
  "lastCountry" varchar(10) DEFAULT NULL,
  "lastRegion" varchar(100) DEFAULT NULL,
  "firstSeen" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "lastSeen" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("deviceId"),
  CONSTRAINT "known_devices_uk_user_fingerprint" UNIQUE ("userId","fingerprint")
);

CREATE TABLE "kycTierHistory" (
  "historyId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "oldTier" varchar(20) NOT NULL,
  "newTier" varchar(20) NOT NULL,
  "reason" varchar(255) DEFAULT NULL,
  "triggeredBy" varchar(50) DEFAULT 'system',
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("historyId")
);

CREATE TABLE "livenessImages" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "imageUrl" varchar(255) NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "imageBlob" bytea,
  PRIMARY KEY ("id")
);

CREATE TABLE "notifications" (
  "id" char(36) NOT NULL,
  "userId" char(36) NOT NULL,
  "title" varchar(255) NOT NULL,
  "message" text NOT NULL,
  "category" varchar(50) NOT NULL,
  "coverImageUrl" text,
  "profileImageUrl" text,
  "actionLabel" varchar(100) DEFAULT NULL,
  "actionRoute" varchar(100) DEFAULT NULL,
  "actionData" jsonb DEFAULT NULL,
  "dateSent" timestamp NULL DEFAULT NULL,
  "isRead" boolean NOT NULL DEFAULT FALSE,
  "isArchived" boolean DEFAULT FALSE,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "otpRequests" (
  "otpRequestId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "requestId" varchar(64) NOT NULL,
  "userId" bigint NOT NULL,
  "channel" varchar(5) NOT NULL CHECK ("channel" IN ('email', 'phone')),
  "purpose" varchar(50) NOT NULL,
  "destination" varchar(255) DEFAULT NULL,
  "otpCode" varchar(255) NOT NULL,
  "status" varchar(9) DEFAULT 'pending' CHECK ("status" IN ('pending', 'verified', 'expired', 'cancelled')),
  "expiresAt" timestamp NOT NULL,
  "verifiedAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("otpRequestId"),
  CONSTRAINT "otpRequests_requestId" UNIQUE ("requestId")
);

CREATE TABLE "passwordResets" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "email" varchar(255) NOT NULL,
  "token" varchar(255) NOT NULL,
  "resetLink" varchar(500) NOT NULL,
  "status" varchar(7) DEFAULT 'active' CHECK ("status" IN ('active', 'used', 'expired')),
  "createdAt" timestamp NOT NULL,
  "expiresAt" timestamp NOT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "pinBlocks" (
  "pinBlockId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "reason" varchar(255) NOT NULL,
  "failedAttempts" integer NOT NULL DEFAULT '0',
  "maxAttempts" integer NOT NULL DEFAULT '5',
  "isBlocked" boolean NOT NULL DEFAULT FALSE,
  "blockedAt" timestamp DEFAULT NULL,
  "unblockAt" timestamp DEFAULT NULL,
  "lastFailedAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("pinBlockId")
);

CREATE TABLE "pinUpdateBlocks" (
  "pinUpdateBlockId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "updatesToday" integer NOT NULL DEFAULT '0',
  "blockReason" varchar(10) NOT NULL DEFAULT 'dailyLimit' CHECK ("blockReason" IN ('dailyLimit')),
  "isBlocked" boolean NOT NULL DEFAULT FALSE,
  "blockedAt" timestamp DEFAULT NULL,
  "unblockAt" timestamp DEFAULT NULL,
  "lastUpdateAt" timestamp DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("pinUpdateBlockId"),
  CONSTRAINT "pinUpdateBlocks_uniq_user" UNIQUE ("userId")
);

CREATE TABLE "pinUpdateHistory" (
  "pinUpdateHistoryId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "updateType" varchar(6) NOT NULL CHECK ("updateType" IN ('setup', 'change', 'reset')),
  "changedByAdminId" integer DEFAULT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "userAgent" varchar(255) DEFAULT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("pinUpdateHistoryId")
);

CREATE TABLE "referralCampaigns" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "campaignCode" varchar(100) NOT NULL,
  "name" varchar(255) NOT NULL,
  "description" text,
  "startDate" date DEFAULT NULL,
  "endDate" date DEFAULT NULL,
  "maxRewards" integer DEFAULT '0',
  "status" varchar(9) NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'active', 'paused', 'ended', 'cancelled')),
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "rewardAmount" decimal(10,2) DEFAULT '10.00',
  "bonusThreshold" decimal(10,2) DEFAULT '50000.00',
  "bonusMultiplier" decimal(5,2) DEFAULT '1.00',
  "slotLimit" integer DEFAULT '0',
  "coverPhoto" varchar(500) DEFAULT NULL,
  "spendLimit" decimal(12,2) DEFAULT '0.00',
  PRIMARY KEY ("id"),
  CONSTRAINT "referralCampaigns_campaignCode" UNIQUE ("campaignCode")
);

CREATE TABLE "referralPayouts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "referrerId" integer NOT NULL,
  "referredId" integer NOT NULL,
  "amount" decimal(15,2) NOT NULL,
  "status" varchar(20) DEFAULT 'success',
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "referralPayouts_uniquePayout" UNIQUE ("referrerId","referredId")
);

CREATE TABLE "referralPendingAlerts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "referrerId" integer NOT NULL,
  "referredId" integer NOT NULL,
  "lastSent" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "referralPendingAlerts_uniqueAlert" UNIQUE ("referrerId","referredId")
);

CREATE TABLE "referralProfiles" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "profileName" varchar(255) NOT NULL,
  "profileCode" varchar(100) NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "referralTier" varchar(50) DEFAULT 'Bronze',
  "registrations" jsonb DEFAULT NULL,
  "promotionCodes" jsonb DEFAULT NULL,
  "payouts" jsonb DEFAULT NULL,
  "pendingAlerts" jsonb DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "referralProfiles_profileCode" UNIQUE ("profileCode")
);

CREATE TABLE "referralTracking" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "referralCode" varchar(50) NOT NULL,
  "source" varchar(50) DEFAULT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "userAgent" text,
  "clickedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "campaign" varchar(100) DEFAULT NULL,
  "promoCode" varchar(100) DEFAULT NULL,
  "profileCode" varchar(100) DEFAULT NULL,
  "utmSource" varchar(100) DEFAULT NULL,
  "utmMedium" varchar(100) DEFAULT NULL,
  "utmCampaign" varchar(100) DEFAULT NULL,
  "utmTerm" varchar(100) DEFAULT NULL,
  "utmContent" varchar(100) DEFAULT NULL,
  "clickIdentifier" varchar(100) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "riskEvents" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "riskType" varchar(50) NOT NULL,
  "amount" decimal(15,2) NOT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "deviceInfo" varchar(255) DEFAULT NULL,
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "safeHavenCompanyProfile" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "rcNumber" varchar(20) NOT NULL,
  "identityId" varchar(50) NOT NULL,
  "linkedBvn" varchar(15) NOT NULL,
  "directorName" varchar(100) DEFAULT NULL,
  "kycStatus" varchar(20) DEFAULT 'VERIFIED',
  "ourAccountNumber" varchar(20) DEFAULT NULL,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "safeHavenConfig" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "environment" varchar(20) NOT NULL,
  "clientId" varchar(255) NOT NULL,
  "clientAssertionType" varchar(255) DEFAULT 'urn:ietf:params:oauth:client-assertion-type:jwt-bearer',
  "baseUrl" varchar(255) DEFAULT 'https://api.sandbox.safehavenmfb.com',
  "companyUrl" varchar(255) DEFAULT 'https://paysmart.com.ng',
  "callbackUrl" varchar(255) DEFAULT NULL,
  "mainAccountNumber" varchar(20) DEFAULT NULL,
  "privateKeyPath" varchar(255) DEFAULT '/home/apdkduzc/api.paysmart.com.ng/config/privatekey.pem',
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "serviceStats" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "serviceName" varchar(50) NOT NULL,
  "totalTransactions" bigint DEFAULT '0',
  "successfulTransactions" bigint DEFAULT '0',
  "failedTransactions" bigint DEFAULT '0',
  "refundedTransactions" bigint DEFAULT '0',
  "successRate" decimal(5,2) DEFAULT '0.00',
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "serviceStats_serviceName" UNIQUE ("serviceName")
);

CREATE TABLE "sessions" (
  "sessionId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "mode" varchar(4) NOT NULL DEFAULT 'live' CHECK ("mode" IN ('live', 'test')),
  "channel" varchar(50) NOT NULL,
  "metadata" jsonb DEFAULT NULL,
  "sessionToken" varchar(255) NOT NULL,
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "expiresAt" timestamp DEFAULT NULL,
  "status" varchar(11) DEFAULT 'active' CHECK ("status" IN ('active', 'expired', 'pending_2fa')),
  "terminationReason" jsonb DEFAULT NULL,
  "ipVirtual" varchar(45) GENERATED ALWAYS AS ("metadata" ->> 'ip') STORED,
  PRIMARY KEY ("sessionId")
);

CREATE TABLE "spendAndSaveSettings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "isEnabled" boolean NOT NULL DEFAULT FALSE,
  "savePercentage" decimal(5,2) NOT NULL DEFAULT '0.00',
  "fixedSaveAmount" decimal(15,2) NOT NULL DEFAULT '0.00',
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "spendAndSaveSettings_uk_spendAndSave_userId" UNIQUE ("userId")
);

CREATE TABLE "supportChats" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "ticketId" varchar(50) DEFAULT NULL,
  "userId" bigint DEFAULT NULL,
  "waId" varchar(100) DEFAULT NULL,
  "whatsappPhone" varchar(30) DEFAULT NULL,
  "isWhatsapp" boolean NOT NULL DEFAULT FALSE,
  "userEmail" varchar(150) DEFAULT NULL,
  "userName" varchar(150) DEFAULT NULL,
  "subject" varchar(255) DEFAULT NULL,
  "issueCategory" varchar(100) DEFAULT NULL,
  "status" varchar(50) NOT NULL DEFAULT 'open',
  "chatState" varchar(100) DEFAULT NULL,
  "lastMessage" text,
  "escalationSummary" text,
  "messages" jsonb NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "tierLimits" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "tier" varchar(8) NOT NULL CHECK ("tier" IN ('tier1', 'tier2', 'tier3', 'merchant')),
  "dailyDeposit" decimal(15,2) NOT NULL DEFAULT '0.00',
  "dailyWithdraw" decimal(15,2) NOT NULL DEFAULT '0.00',
  "weeklyDeposit" decimal(15,2) NOT NULL DEFAULT '0.00',
  "weeklyWithdraw" decimal(15,2) NOT NULL DEFAULT '0.00',
  "monthlyDeposit" decimal(15,2) NOT NULL DEFAULT '0.00',
  "monthlyWithdraw" decimal(15,2) NOT NULL DEFAULT '0.00',
  "yearlyDeposit" decimal(15,2) NOT NULL DEFAULT '0.00',
  "yearlyWithdraw" decimal(15,2) NOT NULL DEFAULT '0.00',
  "updatedAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "transactions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "type" varchar(100) NOT NULL,
  "serviceName" varchar(150) NOT NULL,
  "direction" varchar(10) NOT NULL CHECK ("direction" IN ('credit', 'debit')),
  "amount" decimal(15,2) NOT NULL DEFAULT 0,
  "fee" decimal(15,2) NOT NULL DEFAULT 0,
  "revenue" decimal(15,2) NOT NULL DEFAULT 0,
  "status" varchar(50) NOT NULL,
  "currency" varchar(3) NOT NULL DEFAULT 'NGN',
  "psRef" varchar(50) NOT NULL,
  "sessionReference" varchar(255) DEFAULT NULL,
  "balanceBefore" decimal(15,2) DEFAULT NULL,
  "balanceAfter" decimal(15,2) DEFAULT NULL,
  "narration" text,
  "walletType" varchar(50) NOT NULL DEFAULT 'MAIN',
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "transactions_ps_ref" UNIQUE ("psRef")
);

CREATE TABLE "userInvites" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recipientEmail" varchar(255) NOT NULL,
  "senderId" bigint DEFAULT NULL,
  "inviteToken" varchar(128) NOT NULL,
  "lastInvitedAt" timestamp NOT NULL,
  "createdAt" timestamp NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "userInvites_idx_sender_recipient" UNIQUE ("senderId","recipientEmail")
);

CREATE TABLE "userLoginHistory" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "sessionToken" varchar(255) DEFAULT NULL,
  "eventType" varchar(15) NOT NULL DEFAULT 'loginSuccess' CHECK ("eventType" IN ('loginSuccess', 'loginFailed', 'loginChallenge', 'logout', 'sessionReplaced')),
  "ip" varchar(45) DEFAULT NULL,
  "deviceName" varchar(255) DEFAULT NULL,
  "deviceOs" varchar(255) DEFAULT NULL,
  "fingerprint" varchar(255) DEFAULT NULL,
  "channel" varchar(50) DEFAULT NULL,
  "metadata" jsonb DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "clientMetadata" (
  "metadataId" varchar(53) NOT NULL,
  "channel" varchar(50) DEFAULT NULL,
  "deviceName" varchar(255) DEFAULT NULL,
  "os" varchar(100) DEFAULT NULL,
  "appVersion" varchar(50) DEFAULT NULL,
  "userAgent" varchar(500) DEFAULT NULL,
  "ipAddress" varchar(45) DEFAULT NULL,
  "metadata" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expiresAt" timestamp NOT NULL,
  PRIMARY KEY ("metadataId")
);

CREATE INDEX "clientMetadata_expiresAt" ON "clientMetadata" ("expiresAt");

CREATE TABLE "users" (
  "userId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "mode" varchar(4) NOT NULL DEFAULT 'live' CHECK ("mode" IN ('live', 'test')),
  "firstName" varchar(50) DEFAULT NULL,
  "middleName" varchar(50) DEFAULT NULL,
  "lastName" varchar(50) DEFAULT NULL,
  "fullName" varchar(150) GENERATED ALWAYS AS ("firstName" || ' ' || coalesce("middleName", '') || ' ' || "lastName") STORED,
  "username" varchar(50) DEFAULT NULL,
  "phoneNumber" varchar(20) NOT NULL,
  "email" varchar(100) DEFAULT NULL,
  "dateOfBirth" date DEFAULT NULL,
  "lastBirthdayWishYear" integer DEFAULT '0',
  "gender" varchar(6) DEFAULT NULL CHECK ("gender" IN ('male', 'female', 'other')),
  "countryCode" char(2) DEFAULT NULL,
  "passwordHash" varchar(255) DEFAULT NULL,
  "pinHash" varchar(255) DEFAULT NULL,
  "status" varchar(20) DEFAULT 'active' CHECK ("status" IN ('active', 'blocked', 'suspended', 'closed', 'pending_setup')),
  "isPnd" boolean DEFAULT FALSE,
  "twoFactorAuth" boolean DEFAULT FALSE,
  "isEmailVerified" boolean NOT NULL DEFAULT FALSE,
  "isPhoneVerified" boolean NOT NULL DEFAULT FALSE,
  "kycLevel" varchar(8) NOT NULL DEFAULT 'tier0' CHECK ("kycLevel" IN ('tier0', 'tier1', 'tier2', 'tier3', 'merchant')),
  "kycStatus" varchar(8) DEFAULT 'pending' CHECK ("kycStatus" IN ('pending', 'approved', 'rejected')),
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "referedBy" varchar(20) DEFAULT NULL,
  "referralCode" varchar(20) DEFAULT NULL,
  "yesterdaysEarnings" decimal(12,2) NOT NULL DEFAULT '0.00',
  "todaysEarnings" decimal(12,2) NOT NULL DEFAULT '0.00',
  "singleDeviceLogin" boolean DEFAULT FALSE,
  "registrationSource" varchar(50) DEFAULT 'mobile_app',
  "registrationMetadata" jsonb DEFAULT NULL,
  "kycIdentifier" varchar(50) DEFAULT NULL,
  "avatarBlob" bytea,
  PRIMARY KEY ("userId"),
  CONSTRAINT "users_phone_number" UNIQUE ("phoneNumber"),
  CONSTRAINT "users_email" UNIQUE ("email"),
  CONSTRAINT "users_username" UNIQUE ("username")
);

CREATE TABLE "remitaPayments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL REFERENCES "users"("userId"),
  "environment" varchar(4) NOT NULL CHECK ("environment" IN ('LIVE', 'TEST')),
  "idempotencyKey" varchar(128) NOT NULL,
  "rrr" varchar(64) NOT NULL,
  "psRef" varchar(50) DEFAULT NULL REFERENCES "transactions"("psRef"),
  "amount" decimal(15,2) NOT NULL,
  "currency" varchar(3) NOT NULL DEFAULT 'NGN',
  "status" varchar(20) NOT NULL CHECK ("status" IN ('processing', 'successful', 'refunded')),
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "remitaPayments_uq_idempotency" UNIQUE ("userId","environment","idempotencyKey"),
  CONSTRAINT "remitaPayments_uq_psRef" UNIQUE ("psRef")
);

CREATE UNIQUE INDEX "remitaPayments_uq_pending_rrr" ON "remitaPayments" ("environment","rrr") WHERE "status"='processing';

CREATE TABLE "pushTokens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL REFERENCES "users"("userId") ON DELETE CASCADE,
  "token" text NOT NULL,
  "platform" varchar(20) NOT NULL CHECK ("platform" IN ('android', 'ios', 'web')),
  "provider" varchar(30) NOT NULL,
  "isActive" boolean NOT NULL DEFAULT TRUE,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "pushTokens_uq_user_platform" UNIQUE ("userId","platform")
);

CREATE TABLE "loginSecurity" (
  "userId" bigint NOT NULL REFERENCES "users"("userId") ON DELETE CASCADE,
  "passwordAttempts" integer NOT NULL DEFAULT 0,
  "lockedUntil" timestamp DEFAULT NULL,
  "lastFailedAt" timestamp DEFAULT NULL,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("userId")
);

CREATE TABLE "userSavedCards" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "cardToken" varchar(255) NOT NULL,
  "cardLast4" varchar(20) NOT NULL,
  "cardBrand" varchar(50) NOT NULL,
  "cardExpiry" varchar(20) NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "deletedAt" timestamp DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "userSavedCards_unique_user_card" UNIQUE ("userId","cardToken")
);

CREATE TABLE "userSettings" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "category" varchar(50) NOT NULL DEFAULT 'general',
  "settings" jsonb NOT NULL,
  "updatedAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "userSettings_idx_user_category" UNIQUE ("userId","category")
);

CREATE TABLE "userActivityLogs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "sessionToken" varchar(255) DEFAULT NULL,
  "action" varchar(100) NOT NULL,
  "impactLevel" varchar(8) NOT NULL DEFAULT 'LOW' CHECK ("impactLevel" IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
  "description" text,
  "ipAddress" varchar(45) DEFAULT NULL,
  "userAgent" text,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "userId" bigint NULL,
  "accountType" varchar(5) NOT NULL DEFAULT 'user' CHECK ("accountType" IN ('user', 'admin')),
  PRIMARY KEY ("id")
);

CREATE TABLE "userStreaks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" integer NOT NULL,
  "streakCount" integer DEFAULT '1',
  "lastCheckinDate" date NOT NULL,
  "weekYear" integer NOT NULL,
  "weekNumber" integer NOT NULL,
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "user_streaks_unique_user_week" UNIQUE ("userId","weekYear","weekNumber")
);

CREATE TABLE "virtualAccounts" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "provider" varchar(50) NOT NULL,
  "accountNumber" varchar(20) NOT NULL,
  "accountName" varchar(100) DEFAULT NULL,
  "bankName" varchar(100) DEFAULT NULL,
  "orderRef" varchar(100) DEFAULT NULL,
  "displayName" varchar(100) DEFAULT NULL,
  "runStatus" integer DEFAULT '1',
  "isActive" integer DEFAULT '1',
  "createdAt" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "virtualAccounts_uniqueUserProvider" UNIQUE ("userId","provider"),
  CONSTRAINT "virtualAccounts_unique_user_provider_env" UNIQUE ("userId","provider","environment")
);

CREATE TABLE "wallets" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "walletType" varchar(30) NOT NULL DEFAULT 'MAIN',
  "currency" varchar(10) NOT NULL,
  "balance" decimal(20,8) NOT NULL DEFAULT '0.00000000',
  "availableBalance" decimal(20,8) NOT NULL DEFAULT '0.00000000',
  "pendingBalance" decimal(20,8) NOT NULL DEFAULT '0.00000000',
  "status" boolean NOT NULL DEFAULT TRUE,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "wallets_unique_user_env_type_currency" UNIQUE ("userId","environment","walletType","currency")
);

CREATE TABLE "weeklyLeaderboard" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(10) NOT NULL CHECK ("environment" IN ('LIVE', 'TEST', 'LEGACY')),
  "weekName" varchar(50) DEFAULT NULL,
  "startDate" date NOT NULL,
  "endDate" date NOT NULL,
  "totalAmount" decimal(30,2) NOT NULL DEFAULT '0.00',
  "rank" integer DEFAULT NULL,
  "firstPlaceWinner" varchar(255) DEFAULT NULL,
  "secondPlaceWinner" varchar(255) DEFAULT NULL,
  "thirdPlaceWinner" varchar(255) DEFAULT NULL,
  "isFinalized" boolean DEFAULT FALSE,
  "createdAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "weeklyLeaderboard_unique_user_week_environment" UNIQUE ("userId","startDate","environment")
);

CREATE TABLE "adminWorkspaceActionLogs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "adminId" bigint NOT NULL,
  "entityType" varchar(40) NOT NULL,
  "entityId" bigint NOT NULL,
  "action" varchar(40) NOT NULL,
  "reason" text NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "authRefreshTokens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "accountType" varchar(5) NOT NULL CHECK ("accountType" IN ('user', 'admin')),
  "accountId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL CHECK ("environment" IN ('LIVE', 'TEST')),
  "adminRole" varchar(50) NULL,
  "fingerprint" varchar(255) NOT NULL,
  "deviceName" varchar(100) NOT NULL,
  "channel" varchar(50) NOT NULL,
  "metadata" jsonb NULL,
  "familyId" char(36) NOT NULL,
  "tokenHash" char(64) NOT NULL,
  "expiresAt" timestamp NOT NULL,
  "lastUsedAt" timestamp NULL,
  "revokedAt" timestamp NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "ipAddress" varchar(45) NULL,
  "userAgent" varchar(500) NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "authRefreshTokens_uq_auth_refresh_token_hash" UNIQUE ("tokenHash")
);

CREATE TABLE "emailOutbox" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recipientEmail" varchar(254) NULL,
  "payload" jsonb NULL,
  "status" varchar(10) NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'processing', 'sent', 'failed')),
  "attempts" integer NOT NULL DEFAULT 0,
  "availableAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "lockedAt" timestamp NULL,
  "sentAt" timestamp NULL,
  "lastErrorCode" varchar(100) NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "giftCardCodeResendAttempts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "helpArticleCategories" (
  "categoryId" varchar(80) NOT NULL,
  "name" varchar(120) NOT NULL,
  "slug" varchar(160) NOT NULL,
  "description" text NULL,
  "icon" varchar(80) NULL,
  "status" varchar(8) NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'archived')),
  "createdByAdminId" bigint NULL,
  "updatedByAdminId" bigint NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("categoryId"),
  CONSTRAINT "helpArticleCategories_uq_help_article_categories_slug" UNIQUE ("slug")
);

CREATE TABLE "helpArticles" (
  "id" varchar(80) NOT NULL,
  "slug" varchar(200) NOT NULL,
  "categoryId" varchar(80) NULL,
  "title" varchar(200) NOT NULL,
  "summary" text NULL,
  "content" jsonb NOT NULL,
  "readTime" varchar(40) NULL,
  "isFeatured" boolean NOT NULL DEFAULT FALSE,
  "status" varchar(9) NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'published', 'archived')),
  "createdByAdminId" bigint NULL,
  "updatedByAdminId" bigint NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "helpArticles_uq_help_articles_slug" UNIQUE ("slug"),
  CONSTRAINT "fk_help_articles_category" FOREIGN KEY ("categoryId") REFERENCES "helpArticleCategories" ("categoryId") ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE "helpFaqs" (
  "id" varchar(80) NOT NULL,
  "slug" varchar(200) NOT NULL,
  "question" varchar(500) NOT NULL,
  "answer" text NOT NULL,
  "category" varchar(120) NULL,
  "isFeatured" boolean NOT NULL DEFAULT FALSE,
  "status" varchar(9) NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'published', 'archived')),
  "createdByAdminId" bigint NULL,
  "updatedByAdminId" bigint NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "helpFaqs_uq_help_faqs_slug" UNIQUE ("slug")
);

CREATE TABLE "helpSocialSettings" (
  "id" varchar(40) NOT NULL,
  "links" jsonb NOT NULL,
  "updatedByAdminId" bigint NULL,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "helpLocations" (
  "id" varchar(80) NOT NULL,
  "locationType" varchar(6) NOT NULL CHECK ("locationType" IN ('office', 'agent')),
  "branch" varchar(200) NOT NULL,
  "address" text NOT NULL,
  "hours" varchar(255) NULL,
  "image" text NULL,
  "map" jsonb NULL,
  "sortOrder" integer NOT NULL DEFAULT 0,
  "status" varchar(8) NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'archived')),
  "createdByAdminId" bigint NULL,
  "updatedByAdminId" bigint NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "passwordResetTokens" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "tokenHash" char(64) NOT NULL,
  "purpose" varchar(20) NOT NULL DEFAULT 'reset' CHECK ("purpose" IN ('reset', 'setup')),
  "expiresAt" timestamp NOT NULL,
  "usedAt" timestamp NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "passwordResetTokens_uq_password_reset_token_hash" UNIQUE ("tokenHash")
);

CREATE TABLE "systemSettings" (
  "id" varchar(32) NOT NULL,
  "maintenanceEnabled" boolean NOT NULL DEFAULT FALSE,
  "limitsTestBypass" boolean NOT NULL DEFAULT FALSE,
  "updatedByAdminId" bigint NULL,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "userWebhooks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL DEFAULT 'LIVE' CHECK ("environment" IN ('LIVE', 'TEST')),
  "url" varchar(500) NOT NULL,
  "secret" varchar(128) NOT NULL,
  "isActive" boolean NOT NULL DEFAULT TRUE,
  "description" varchar(150) NULL,
  "lastSuccessAt" timestamp NULL,
  "lastFailureAt" timestamp NULL,
  "failureCount" bigint NOT NULL DEFAULT 0,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "userWebhooks_ukUserEnv" UNIQUE ("userId","environment")
);

CREATE TABLE "giftCardPurchaseRequests" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "environment" varchar(4) NOT NULL CHECK ("environment" IN ('LIVE', 'TEST')),
  "idempotencyKey" varchar(128) DEFAULT NULL,
  "requestHash" char(64) NOT NULL,
  "reference" varchar(100) NOT NULL,
  "productId" varchar(80) DEFAULT NULL,
  "quantity" integer DEFAULT NULL,
  "unitPrice" decimal(15,2) DEFAULT NULL,
  "fxRateUsdToNgn" decimal(15,6) DEFAULT NULL,
  "recipientPhoneDetails" jsonb DEFAULT NULL,
  "preOrder" boolean NOT NULL DEFAULT FALSE,
  "customerEmail" varchar(255) DEFAULT NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "giftCardPurchaseRequests_uq_gift_card_purchase_idempotency" UNIQUE ("userId","environment","idempotencyKey"),
  CONSTRAINT "giftCardPurchaseRequests_uq_gift_card_purchase_reference" UNIQUE ("reference")
);

CREATE TABLE "userProviderAccounts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "userId" bigint NOT NULL,
  "provider" varchar(50) NOT NULL,
  "environment" varchar(20) NOT NULL,
  "providerCustomerId" varchar(100) NULL,
  "providerAccountId" varchar(100) NULL,
  "status" varchar(30) NOT NULL DEFAULT 'active',
  "metadata" jsonb NULL,
  "createdAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "userProviderAccounts_uqUserProviderEnv" UNIQUE ("userId","provider","environment")
);

