CREATE OR REPLACE FUNCTION "apply_auto_update_timestamp"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW := jsonb_populate_record(NEW, jsonb_build_object(TG_ARGV[0], CURRENT_TIMESTAMP));
  RETURN NEW;
END;
$$;

DO $$
DECLARE
  timestamp_column record;
BEGIN
  FOR timestamp_column IN
    SELECT * FROM (VALUES
      ('adminCustomerRestrictions', 'updatedAt'),
      ('adminKnownDevices', 'lastSeen'),
      ('beneficiaries', 'updatedAt'),
      ('campaigns', 'updatedAt'),
      ('cookies', 'updatedAt'),
      ('dataPlans', 'lastChecked'),
      ('featureSuggestions', 'updatedAt'),
      ('giftCardSubmissions', 'updatedAt'),
      ('invoices', 'updatedAt'),
      ('loginSecurity', 'updatedAt'),
      ('knownDevices', 'lastSeen'),
      ('notifications', 'updatedAt'),
      ('pushTokens', 'updatedAt'),
      ('pinBlocks', 'updatedAt'),
      ('pinUpdateBlocks', 'updatedAt'),
      ('safeHavenCompanyProfile', 'updatedAt'),
      ('safeHavenConfig', 'updatedAt'),
      ('serviceStats', 'updatedAt'),
      ('spendAndSaveSettings', 'updatedAt'),
      ('supportChats', 'updatedAt'),
      ('tierLimits', 'updatedAt'),
      ('transactions', 'updatedAt'),
      ('userSettings', 'updatedAt'),
      ('wallets', 'updatedAt'),
      ('weeklyLeaderboard', 'updatedAt')
    ) AS timestamps(table_name, column_name)
  LOOP
    EXECUTE format(
      'CREATE TRIGGER %I BEFORE UPDATE ON public.%I FOR EACH ROW WHEN (OLD.%I IS NOT DISTINCT FROM NEW.%I) EXECUTE FUNCTION public.%I(%L)',
      'trg_atu_' || timestamp_column.table_name,
      timestamp_column.table_name,
      timestamp_column.column_name,
      timestamp_column.column_name,
      'apply_auto_update_timestamp',
      timestamp_column.column_name
    );
  END LOOP;
END;
$$;
